import * as T from './vendor/three.module.js';
export function botanicalPart(geometry,color,position=[0,0,0],scale=[1,1,1],rotation=[0,0,0]){const o=new T.Object3D();o.position.fromArray(position);o.scale.fromArray(scale);o.rotation.set(...rotation);o.updateMatrix();return{geometry,color,matrix:o.matrix};}
export function mergeBotanical(parts){const p=[],n=[],c=[];for(const part of parts){const g=part.geometry.index?part.geometry.toNonIndexed():part.geometry.clone();g.applyMatrix4(part.matrix);const pos=g.attributes.position,norm=g.attributes.normal,col=new T.Color(part.color);for(let i=0;i<pos.count;i++){p.push(pos.getX(i),pos.getY(i),pos.getZ(i));n.push(norm.getX(i),norm.getY(i),norm.getZ(i));c.push(col.r,col.g,col.b);}g.dispose();}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('normal',new T.Float32BufferAttribute(n,3));g.setAttribute('color',new T.Float32BufferAttribute(c,3));return g;}
export function leafBlade(length=.28,width=.03){const p=[],ix=[];for(let i=0;i<=7;i++){const t=i/7,w=Math.sin(Math.PI*t)*width;for(const side of[-1,1])p.push(side*w,.11*Math.sin(Math.PI*t)-.09*t*t,t*length);if(i){const k=i*2;ix.push(k-2,k,k-1,k-1,k,k+1);}}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setIndex(ix);g.computeVertexNormals();return g;}
